import React, { useState } from 'react';
import { QrCode, Camera, CheckCircle2, AlertTriangle, FileCode, RefreshCw, X, ArrowRight } from 'lucide-react';
import { Patient, DailyLog, NeuroStatus } from '../types/clinical';

interface QrScannerModalProps {
  isOpen: boolean;
  onClose: () => void;
  patients: Patient[];
  onImportQrData: (patientId: string, importedLogs: DailyLog[]) => void;
}

export const QrScannerModal: React.FC<QrScannerModalProps> = ({
  isOpen,
  onClose,
  patients,
  onImportQrData,
}) => {
  if (!isOpen) return null;

  // Sample compact payloads generated by rural offline app
  const samplePayloadRosa = 'KUMELEN|v2|PAT:ARAUC-ROSA-88|KM:18|D1:2_L1_LUCID|D2:3_L1_LUCID|D3:2_L1_LUCID|D4:1_L1_DROWSY|D5:2_L1_LUCID|D6:1_L1_DROWSY|D7:2_L1_LUCID|SYNC:POSTA_BOROA';
  const samplePayloadLorenzo = 'KUMELEN|v2|PAT:ARAUC-LORE-59|KM:32|D1:2_L1_LUCID|D2:1_L1_DROWSY|D3:1_L0_DROWSY|D4:0_L0_CONFUSED|D5:0_L0_CONFUSED|D6:0_L0_CONFUSED|D7:0_L0_CONFUSED|SYNC:PUERTO_DOMINGUEZ';

  const [rawPayload, setRawPayload] = useState<string>(samplePayloadRosa);
  const [isScanning, setIsScanning] = useState<boolean>(false);
  const [decodedData, setDecodedData] = useState<{
    patientCode: string;
    patientName: string;
    patientId: string;
    km: number;
    daysCount: number;
    todayStools: number;
    todayNeuro: NeuroStatus;
    todayLactulose: boolean;
    logs: DailyLog[];
  } | null>(null);

  const handleScanSimulation = (payloadToScan: string) => {
    setIsScanning(true);
    setRawPayload(payloadToScan);
    setDecodedData(null);

    setTimeout(() => {
      setIsScanning(false);
      try {
        const parts = payloadToScan.split('|');
        const patPart = parts.find((p) => p.startsWith('PAT:'));
        const kmPart = parts.find((p) => p.startsWith('KM:'));

        if (!patPart) {
          throw new Error('Formato de código QR no reconocido');
        }

        const patCode = patPart.replace('PAT:', '');
        const matchedPatient = patients.find((p) => p.code === patCode) || patients[1];

        // Parse days D1 to D7
        const dayParts = parts.filter((p) => /^D\d:/.test(p));
        const dayLabels = ['Jue 01', 'Vie 02', 'Sáb 03', 'Dom 04', 'Lun 05', 'Mar 06', 'Hoy'];

        const parsedLogs: DailyLog[] = dayParts.map((dp, idx) => {
          const content = dp.split(':')[1]; // e.g. 2_L1_LUCID
          const [stoolsStr, lactStr, neuroStr] = content.split('_');
          return {
            date: `2026-10-0${idx + 1}`,
            dayLabel: dayLabels[idx] || `Día ${idx + 1}`,
            stools: parseInt(stoolsStr, 10) || 0,
            lactuloseAdherence: lactStr === 'L1',
            neuroStatus: (neuroStr as NeuroStatus) || 'LUCID',
            syncSource: 'qr_posta',
            syncTime: '11:15',
            symptomsNote: 'Dato importado ópticamente en Posta sin internet.',
          };
        });

        const latestParsed = parsedLogs[parsedLogs.length - 1];

        setDecodedData({
          patientCode: patCode,
          patientName: matchedPatient.name,
          patientId: matchedPatient.id,
          km: kmPart ? parseInt(kmPart.replace('KM:', ''), 10) : matchedPatient.socioDemographic.distanceKm,
          daysCount: parsedLogs.length,
          todayStools: latestParsed?.stools ?? 2,
          todayNeuro: latestParsed?.neuroStatus ?? 'LUCID',
          todayLactulose: latestParsed?.lactuloseAdherence ?? true,
          logs: parsedLogs,
        });
      } catch (err) {
        alert('Error al decodificar trama QR offline.');
      }
    }, 800);
  };

  const handleImport = () => {
    if (!decodedData) return;
    onImportQrData(decodedData.patientId, decodedData.logs);
    onClose();
  };

  return (
    <div className="fixed inset-0 z-50 bg-slate-900/60 backdrop-blur-xs flex items-center justify-center p-4">
      <div className="bg-white rounded-2xl max-w-2xl w-full max-h-[90vh] overflow-y-auto shadow-2xl border border-slate-200">
        {/* Header */}
        <div className="p-4 sm:p-5 border-b border-slate-100 flex items-center justify-between bg-slate-50/70">
          <div className="flex items-center gap-2.5">
            <div className="w-9 h-9 rounded-lg bg-teal-600 text-white flex items-center justify-center">
              <QrCode className="w-5 h-5" />
            </div>
            <div>
              <h2 className="text-base font-bold text-slate-900">
                Escanear Pase QR Óptico (Posta Sin Internet)
              </h2>
              <p className="text-xs text-slate-500">
                Transmisión offline: el paciente muestra su pantalla y la cámara de la Posta decodifica 7 días
              </p>
            </div>
          </div>
          <button
            onClick={onClose}
            className="p-1.5 rounded-lg text-slate-400 hover:text-slate-600 hover:bg-slate-100 cursor-pointer"
          >
            <X className="w-5 h-5" />
          </button>
        </div>

        <div className="p-4 sm:p-6 space-y-4">
          {/* Viewfinder simulation box */}
          <div className="relative rounded-2xl bg-slate-950 overflow-hidden border-2 border-slate-800 p-6 flex flex-col items-center justify-center min-h-[220px]">
            {/* Corner brackets for viewfinder */}
            <div className="absolute top-4 left-4 w-6 h-6 border-t-2 border-l-2 border-teal-400 rounded-tl-md pointer-events-none" />
            <div className="absolute top-4 right-4 w-6 h-6 border-t-2 border-r-2 border-teal-400 rounded-tr-md pointer-events-none" />
            <div className="absolute bottom-4 left-4 w-6 h-6 border-b-2 border-l-2 border-teal-400 rounded-bl-md pointer-events-none" />
            <div className="absolute bottom-4 right-4 w-6 h-6 border-b-2 border-r-2 border-teal-400 rounded-br-md pointer-events-none" />

            {/* Scanning beam animation */}
            {isScanning && (
              <div className="absolute inset-x-8 top-0 h-1 bg-gradient-to-r from-teal-400 via-emerald-300 to-teal-400 shadow-[0_0_15px_#2dd4bf] animate-[bounce_1.5s_infinite]" />
            )}

            {/* QR Pattern Display */}
            <div className="w-32 h-32 bg-white p-2.5 rounded-xl shadow-lg flex flex-col items-center justify-center border border-slate-300 relative group">
              <QrCode className="w-full h-full text-slate-900" />
              {isScanning && (
                <div className="absolute inset-0 bg-teal-500/20 backdrop-blur-[1px] flex items-center justify-center rounded-xl">
                  <span className="text-[11px] font-bold text-white bg-teal-800/90 px-2 py-0.5 rounded shadow">
                    Leyendo...
                  </span>
                </div>
              )}
            </div>

            <p className="text-xs text-slate-400 mt-4 text-center">
              {isScanning
                ? 'Decodificando trama binaria compacta...'
                : 'Apunta la cámara al teléfono rural del paciente en el mesón de la Posta.'}
            </p>
          </div>

          {/* Preset Buttons for Quick Testing */}
          <div>
            <span className="text-xs font-semibold text-slate-700 uppercase tracking-wider block mb-1.5">
              Tarjetas QR de Prueba Rápida:
            </span>
            <div className="flex flex-wrap gap-2">
              <button
                type="button"
                onClick={() => handleScanSimulation(samplePayloadRosa)}
                className="px-3 py-1.5 rounded-lg bg-teal-50 hover:bg-teal-100 text-teal-800 text-xs font-semibold border border-teal-200 transition-colors cursor-pointer"
              >
                Pase Sra. Rosa (Boroa - 18 km)
              </button>
              <button
                type="button"
                onClick={() => handleScanSimulation(samplePayloadLorenzo)}
                className="px-3 py-1.5 rounded-lg bg-rose-50 hover:bg-rose-100 text-rose-800 text-xs font-semibold border border-rose-200 transition-colors cursor-pointer"
              >
                Pase Don Lorenzo (Budi - 32 km)
              </button>
            </div>
          </div>

          {/* Raw payload representation */}
          <div>
            <label className="block text-xs font-semibold text-slate-700 mb-1">
              Trama compacta decodificada:
            </label>
            <div className="p-2.5 rounded-lg bg-slate-900 text-slate-200 font-mono text-[11px] break-all border border-slate-800">
              {rawPayload}
            </div>
          </div>

          {/* Decoded results panel */}
          {decodedData && (
            <div className="p-4 rounded-xl bg-teal-50/80 border border-teal-200 space-y-2 animate-in fade-in duration-200">
              <div className="flex items-center justify-between">
                <span className="text-xs font-bold text-teal-900 flex items-center gap-1.5">
                  <CheckCircle2 className="w-4 h-4 text-teal-600" />
                  Pase QR Validado Exitosamente
                </span>
                <span className="text-xs font-mono font-semibold text-teal-800 bg-white px-2 py-0.5 rounded border border-teal-200">
                  {decodedData.patientCode}
                </span>
              </div>

              <div className="grid grid-cols-2 sm:grid-cols-4 gap-2 pt-2 text-xs">
                <div className="bg-white p-2 rounded-lg border border-teal-100">
                  <span className="text-[10px] text-slate-500 block">Paciente:</span>
                  <span className="font-semibold text-slate-800 truncate block">
                    {decodedData.patientName}
                  </span>
                </div>
                <div className="bg-white p-2 rounded-lg border border-teal-100">
                  <span className="text-[10px] text-slate-500 block">Días Recuperados:</span>
                  <span className="font-semibold font-mono text-slate-800">
                    {decodedData.daysCount} días completos
                  </span>
                </div>
                <div className="bg-white p-2 rounded-lg border border-teal-100">
                  <span className="text-[10px] text-slate-500 block">Hoy (Deposiciones):</span>
                  <span className="font-semibold font-mono text-slate-800">
                    {decodedData.todayStools} veces
                  </span>
                </div>
                <div className="bg-white p-2 rounded-lg border border-teal-100">
                  <span className="text-[10px] text-slate-500 block">Sensorio / Lactulosa:</span>
                  <span className="font-semibold text-slate-800">
                    {decodedData.todayNeuro} · {decodedData.todayLactulose ? 'Lactulosa (+)' : 'Omisión'}
                  </span>
                </div>
              </div>
            </div>
          )}
        </div>

        {/* Footer */}
        <div className="p-4 sm:p-5 border-t border-slate-100 bg-slate-50/70 flex items-center justify-between">
          <span className="text-xs text-slate-500">
            Cumple protocolo MINSAL para Postas Rurales sin factibilidad de fibra ni 4G.
          </span>
          <div className="flex items-center gap-2">
            <button
              onClick={onClose}
              className="px-3.5 py-2 text-xs font-medium text-slate-600 hover:text-slate-900 cursor-pointer"
            >
              Cerrar
            </button>
            <button
              onClick={handleImport}
              disabled={!decodedData}
              className="inline-flex items-center gap-1.5 px-4 py-2 rounded-xl bg-teal-600 hover:bg-teal-500 text-white text-xs font-semibold shadow-sm transition-all cursor-pointer disabled:opacity-40"
            >
              <span>Importar 7 Días a Ficha</span>
              <ArrowRight className="w-3.5 h-3.5" />
            </button>
          </div>
        </div>
      </div>
    </div>
  );
};
